/// <summary>Field classification (RMS plan section 5.9.2). Restricted gates on RecordRestricted_View; Protected is sealed under ADP once cataloged.</summary>
public enum RmsFieldClassification
{
	Standard = 0,
	Restricted = 1,
	Protected = 2
}

public class RecordFieldSchema
{
	public string Key { get; set; }
	public string Label { get; set; }
	public string Help { get; set; }
	public RmsFieldType Type { get; set; }
	/// <summary>Required whenever visible (checked at finalize; drafts may be incomplete).</summary>
	public bool Required { get; set; }
	public bool RequiredToFinalize { get; set; }
	public RmsFieldClassification Classification { get; set; }
	[JsonProperty(Required = Newtonsoft.Json.Required.DisallowNull)]
	public List<RecordOptionSchema> Options { get; set; } = new List<RecordOptionSchema>();

await EnsureRecordsUsableAsync(departmentId);
if (!await _authorization.HasPermissionAsync(userId, departmentId, PermissionTypes.CreateRecord))
	throw new UnauthorizedAccessException("Record creation is not authorized.");

var scopedKey = string.IsNullOrWhiteSpace(input.IdempotencyKey) ? null
	: RecordSnapshotSerializer.Checksum(JsonConvert.SerializeObject(new { departmentId, userId, operation = "CreateDraft", key = input.IdempotencyKey.Trim() }));
var request = Newtonsoft.Json.Linq.JObject.FromObject(input);
request.Remove(nameof(RecordDraftInput.IdempotencyKey));
var requestChecksum = RecordSnapshotSerializer.Checksum(request.ToString(Formatting.None));
if (scopedKey != null)
{
	var existing = await _records.GetByIdempotencyKeyAsync(departmentId, scopedKey);
	if (existing != null)
		return await ReplayCreateAsync(departmentId, userId, existing, requestChecksum);
}

var now = DateTime.UtcNow;
var recordId = ResolveClientRecordId(input.ClientRecordId);
var authorGroup = await _groups.GetGroupForUserAsync(userId, departmentId);

private static string ResolveClientRecordId(string clientRecordId)
{
	if (string.IsNullOrWhiteSpace(clientRecordId))
		return Guid.NewGuid().ToString();
	if (!Guid.TryParse(clientRecordId, out var parsed))
		throw new ArgumentException("A client-supplied record id must be a GUID.", nameof(clientRecordId));
	return parsed.ToString();
}

public static RecordValuesData ToValues(RecordValueSet set, RecordDefinitionSchema schema, bool canViewRestricted, IRecordTypedValuesService typedValues = null)
{
	if (set == null) return null;
	var data = new RecordValuesData { DefinitionKey = set.DefinitionKey, DefinitionVersion = set.DefinitionVersion, WithheldFieldKeys = set.WithheldFieldKeys.ToList() };
	foreach (var section in set.Sections)
	{
		var sectionData = new RecordValueSectionData { SectionKey = section.SectionKey, Label = section.Label, Repeating = section.Repeating };
		foreach (var row in section.Rows)
		{
			var rowData = new RecordValueRowData { RowKey = row.RowKey, Ordinal = row.Ordinal };
			foreach (var cell in row.Cells)
			{
				var withheld = cell.Withheld || cell.Classification == RmsFieldClassification.Restricted && !canViewRestricted;
				if (withheld && !data.WithheldFieldKeys.Contains(cell.FieldKey)) data.WithheldFieldKeys.Add(cell.FieldKey);
				rowData.Cells.Add(new RecordValueCellData
				{
					FieldKey = cell.FieldKey, Label = cell.Label, Type = cell.Type.ToString(), Classification = cell.Classification.ToString(), Withheld = withheld,
					Display = withheld ? (cell.Display == null ? null : RecordTypedValuesService.Redacted) : cell.Display,
					Value = withheld ? null : cell.Value, Values = withheld ? null : cell.Values, ReferenceType = withheld ? null : cell.ReferenceType, ReferenceId = withheld ? null : cell.ReferenceId,
					UnitCode = cell.UnitCode, CurrencyCode = cell.CurrencyCode, OffsetMinutes = cell.OffsetMinutes, Number = withheld ? null : cell.Number, CanonicalNumber = withheld ? null : cell.CanonicalNumber, CanonicalUnitCode = cell.CanonicalUnitCode
				});
			}
			sectionData.Rows.Add(rowData);
		}
		data.Sections.Add(sectionData);

public class RecordValueCellData
{
	public string FieldKey { get; set; }
	public string Label { get; set; }
	public string Type { get; set; }
	public string Classification { get; set; }
	public string Display { get; set; }
	public string Value { get; set; }
	public List<string> Values { get; set; }
	public string ReferenceType { get; set; }
	public string ReferenceId { get; set; }
	public string UnitCode { get; set; }
	public string CurrencyCode { get; set; }
	public int? OffsetMinutes { get; set; }
	public decimal? Number { get; set; }
	public decimal? CanonicalNumber { get; set; }
	public string CanonicalUnitCode { get; set; }
	public bool Withheld { get; set; }
}

public class RecordValueRowData
{
	public string RowKey { get; set; }
	public int Ordinal { get; set; }
	public List<RecordValueCellData> Cells { get; set; } = new List<RecordValueCellData>();
}

public class RecordValueSectionData
{
	public string SectionKey { get; set; }
	public string Label { get; set; }
	public bool Repeating { get; set; }
	public List<RecordValueRowData> Rows { get; set; } = new List<RecordValueRowData>();
}

public class RecordRowRulesData
{
	public string SectionKey { get; set; }
	public string RowKey { get; set; }
	public List<string> HiddenFieldKeys { get; set; } = new List<string>();
	public List<string> RequiredFieldKeys { get; set; } = new List<string>();
}

public class RecordValuesData
{
	public string DefinitionKey { get; set; }
	public int DefinitionVersion { get; set; }
	public List<RecordValueSectionData> Sections { get; set; } = new List<RecordValueSectionData>();
	public List<string> WithheldFieldKeys { get; set; } = new List<string>();
	public List<string> HiddenSectionKeys { get; set; } = new List<string>();
	public List<string> HiddenFieldKeys { get; set; } = new List<string>();
	public List<string> RequiredFieldKeys { get; set; } = new List<string>();
	/// <summary>Per-row rule outcomes for repeating sections (a field rule may look at its own row).</summary>
	public List<RecordRowRulesData> RowRules { get; set; } = new List<RecordRowRulesData>();
